{
  "checks": [
    {
      "candidate_id": "pm",
      "verdict": "SUPPORT",
      "reason": "PM 是明确参与组织行为的角色；这不支持将 PM 另行绑定为读取检查的执行者。",
      "sources": [{"quote":"请 PM 组织","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "请求明确要求组织执行读取检查，组织是主谓词。",
      "sources": [{"quote":"请 PM 组织执行备份读取检查","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "read_check",
      "verdict": "SUPPORT",
      "reason": "执行读取检查是所要求组织的活动补语，具有要求性；源文没有指定实际执行者。",
      "sources": [{"quote":"请 PM 组织执行备份读取检查","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "backup",
      "verdict": "SUPPORT",
      "reason": "备份是读取对象，并受到明确写入禁令，支持只读输入解释。",
      "sources": [
        {"quote":"备份读取检查","clause_id":"c1","occurrence":0,"context_anchor":null},
        {"quote":"不得写入备份","clause_id":"c1","occurrence":0,"context_anchor":null}
      ]
    },
    {
      "candidate_id": "read_success",
      "verdict": "SUPPORT",
      "reason": "读取成功是完成验收门槛中的状态，没有被建模为独立执行命令。",
      "sources": [{"quote":"至少 2 次读取成功且 check-log.md 已生成时任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "check_log",
      "verdict": "SUPPORT",
      "reason": "日志文件以已生成产物的身份出现在完成条件中；GENERATED_OUTPUT 不应被理解为独立生成义务。",
      "sources": [{"quote":"check-log.md 已生成时任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "log_generated",
      "verdict": "SUPPORT",
      "reason": "已生成是完成条件所引用的状态，UNSTATED 保留了没有独立生成命令的区别。",
      "sources": [{"quote":"check-log.md 已生成时任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "completion",
      "verdict": "SUPPORT",
      "reason": "“才完成”明确表达必要完成门槛，不是普通时间背景，也没有明确保证条件满足即充分完成。",
      "sources": [{"quote":"至少 2 次读取成功且 check-log.md 已生成时任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "write_backup",
      "verdict": "SUPPORT",
      "reason": "写入备份受到明确禁止；FORBIDDEN 与 NEGATED 均有否定禁令证据。",
      "sources": [{"quote":"不得写入备份","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_pm_organize",
      "verdict": "SUPPORT",
      "reason": "PM 被直接指定为组织行为的参与者，依据来自谓词绑定而非角色名称。",
      "sources": [{"quote":"请 PM 组织","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_organize_execution",
      "verdict": "CONTRADICT",
      "reason": "源文支持组织行为以执行读取检查为活动补语，但给定 THEME 签名只允许 ENTITY 或 UNKNOWN_REFERENT 尾端；read_check 是 EVENT，此候选违反有限关系合同。",
      "sources": [{"quote":"组织执行备份读取检查","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_read_backup",
      "verdict": "SUPPORT",
      "reason": "备份是读取检查所作用的材料。",
      "sources": [{"quote":"备份读取检查","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_attempt_cap",
      "verdict": "SUPPORT",
      "reason": "紧接读取检查的尝试上限约束该执行活动。",
      "sources": [{"quote":"执行备份读取检查，最多尝试 5 次","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_success_read",
      "verdict": "SUPPORT",
      "reason": "相邻语境支持将成功读取状态关联为前述读取检查的一部分；引用同时见证检查活动与成功读取状态。",
      "sources": [{"quote":"备份读取检查，最多尝试 5 次。至少 2 次读取成功","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_generated_log",
      "verdict": "SUPPORT",
      "reason": "已生成状态的对象是明确命名的日志文件，尾端类型符合 THEME 签名。",
      "sources": [{"quote":"check-log.md 已生成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_completion_state",
      "verdict": "SUPPORT",
      "reason": "完成状态明确属于任务。",
      "sources": [{"quote":"任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_completion_conditions",
      "verdict": "SUPPORT",
      "reason": "合取条件是任务完成的必要门槛，符合条件表达式至 TASK 的 COMPLETION_OF 签名。",
      "sources": [{"quote":"至少 2 次读取成功且 check-log.md 已生成时任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_only_when",
      "verdict": "SUPPORT",
      "reason": "该条件约束任务的完成，结合完成节点及 COMPLETION_OF 关系可支持这一任务级绑定；不能扩展为执行前提或充分完成条件。",
      "sources": [{"quote":"至少 2 次读取成功且 check-log.md 已生成时任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_write_backup",
      "verdict": "SUPPORT",
      "reason": "被禁止写入的对象明确是备份。",
      "sources": [{"quote":"写入备份","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "r_forbid_write",
      "verdict": "SUPPORT",
      "reason": "任务文本明确禁止写入备份，不依赖任何角色权限推断。",
      "sources": [{"quote":"不得写入备份","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "attempt_cap",
      "verdict": "SUPPORT",
      "reason": "最多五次表示执行尝试次数不超过五，属于执行上限而非产物数或成功次数。",
      "sources": [{"quote":"执行备份读取检查，最多尝试 5 次","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "success_threshold",
      "verdict": "SUPPORT",
      "reason": "至少两次成功读取是完成验收阈值，不是最多尝试次数的替代值。",
      "sources": [{"quote":"至少 2 次读取成功且 check-log.md 已生成时任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "generated_condition",
      "verdict": "SUPPORT",
      "reason": "表达式引用日志已生成状态作为完成条件，没有将状态引用提升为生成执行义务。",
      "sources": [{"quote":"check-log.md 已生成时任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    },
    {
      "candidate_id": "completion_guard",
      "verdict": "SUPPORT",
      "reason": "“且”明确要求成功读取阈值与日志生成状态同时满足，作为必要完成门槛。",
      "sources": [{"quote":"至少 2 次读取成功且 check-log.md 已生成时任务才完成","clause_id":"c1","occurrence":0,"context_anchor":null}]
    }
  ],
  "findings": [
    {
      "id": "f_invalid_activity_binding",
      "kind": "WRONG_BINDING",
      "candidate_ids": ["r_organize_execution"],
      "sources": [{"quote":"组织执行备份读取检查","clause_id":"c1","occurrence":0,"context_anchor":null}],
      "reason": "活动补语关系有源文依据，但 EVENT 至 EVENT 的 THEME 绑定不在给定签名内。应显式保留这一合同与源文表达之间的表示冲突；不能通过将读取检查改成实体或猜测另一种关系来强行消除。"
    },
    {
      "id": "f_unreliable_region_coverage",
      "kind": "COVERAGE_GAP",
      "candidate_ids": ["r_organize_execution"],
      "sources": [{"quote":"请 PM 组织执行备份读取检查","clause_id":"c1","occurrence":0,"context_anchor":null}],
      "reason": "组织行为与所组织执行活动之间的边界绑定未获得合同有效的表示，因此 c1 的完整 BOUNDARY_SEMANTIC 覆盖声明不能成立。其余数量、完成条件和禁令有支持证据。"
    }
  ],
  "coverage": [
    {
      "region_id": "c1",
      "disposition": "UNPARSED",
      "candidate_ids": [
        "pm",
        "organize",
        "read_check",
        "backup",
        "read_success",
        "check_log",
        "log_generated",
        "completion",
        "write_backup",
        "r_pm_organize",
        "r_organize_execution",
        "r_read_backup",
        "r_attempt_cap",
        "r_success_read",
        "r_generated_log",
        "r_completion_state",
        "r_completion_conditions",
        "r_only_when",
        "r_write_backup",
        "r_forbid_write",
        "attempt_cap",
        "success_threshold",
        "generated_condition",
        "completion_guard"
      ],
      "reason": "该区域包含明确边界语义，大部分候选有支持；组织与执行活动之间的 THEME 关系违反有限签名，使该项绑定仍未可靠解析。实际读取执行者未指定，日志生成仅以完成状态条件出现，这两点本身不构成遗漏。"
    }
  ],
  "additional_candidates": {
    "nodes": [],
    "relations": [],
    "expressions": [],
    "unresolved": []
  }
}
